//! EIP-1559 construction tests, cross-checked against viem.
//!
//! CLAUDE.md §7 requires the signed transaction hash to match an independently
//! computed reference. `tests/fixtures/eip1559.json` is generated by
//! `scripts/gen-evm-fixtures.mjs` using viem, which shares no code with the
//! Rust encoder. If either implementation drifts, these fail.
//!
//! The fixtures deliberately include RLP's awkward cases: zero (which encodes
//! as the empty string, not `0x00`), the 0x7f/0x80 single-byte boundary, and a
//! payload long enough to need the >55-byte list header.

mod common;
use common::*;

use keyring_contract::evm::{
    address_bytes, rlp_uint, to_be_minimal, Eip1559Transfer, EvmParams, EvmParamsError,
    BASE_SEPOLIA_CHAIN_ID, MAX_TRANSFER_GAS, MIN_TRANSFER_GAS,
};
use near_sdk::json_types::{U128, U64};
use near_sdk::serde_json;
use near_sdk::test_utils::VMContextBuilder;
use near_sdk::testing_env;

const FIXTURES: &str = include_str!("fixtures/eip1559.json");

fn hex_of(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(2 + bytes.len() * 2);
    s.push_str("0x");
    for b in bytes {
        s.push(char::from_digit(u32::from(b >> 4), 16).unwrap());
        s.push(char::from_digit(u32::from(b & 0x0f), 16).unwrap());
    }
    s
}

fn hex_to_32(s: &str) -> [u8; 32] {
    let h = s.strip_prefix("0x").unwrap_or(s);
    let mut out = [0u8; 32];
    for (i, c) in h.as_bytes().chunks(2).enumerate() {
        let hi = (c[0] as char).to_digit(16).unwrap();
        let lo = (c[1] as char).to_digit(16).unwrap();
        out[i] = (hi * 16 + lo) as u8;
    }
    out
}

/// keccak256 is a host function, so a VM context must exist.
fn vm() {
    testing_env!(VMContextBuilder::new().build());
}

// ------------------------------------------------------ viem cross-check

#[test]
fn every_transaction_matches_the_viem_reference() {
    vm();
    let doc: serde_json::Value = serde_json::from_str(FIXTURES).expect("fixtures parse");
    let fixtures = doc["fixtures"].as_array().expect("fixtures array");
    assert!(!fixtures.is_empty(), "fixture file must not be empty");

    for f in fixtures {
        let name = f["name"].as_str().unwrap();
        let tx = Eip1559Transfer {
            chain_id: f["chain_id"].as_u64().unwrap(),
            nonce: f["nonce"].as_u64().unwrap(),
            max_priority_fee_per_gas: f["max_priority_fee_per_gas"]
                .as_str()
                .unwrap()
                .parse()
                .unwrap(),
            max_fee_per_gas: f["max_fee_per_gas"].as_str().unwrap().parse().unwrap(),
            gas_limit: f["gas_limit"].as_str().unwrap().parse().unwrap(),
            to: address_bytes(f["to"].as_str().unwrap()).expect("fixture address"),
            value: f["value"].as_str().unwrap().parse().unwrap(),
        };

        assert_eq!(
            hex_of(&tx.unsigned_encoding()),
            f["unsigned_rlp"].as_str().unwrap(),
            "{name}: unsigned RLP differs from viem"
        );
        assert_eq!(
            hex_of(&tx.signing_hash()),
            f["signing_hash"].as_str().unwrap(),
            "{name}: signing hash differs from viem"
        );

        let r = hex_to_32(f["signature"]["r"].as_str().unwrap());
        let s = hex_to_32(f["signature"]["s"].as_str().unwrap());
        let y = f["signature"]["yParity"].as_u64().unwrap() as u8;
        assert_eq!(
            hex_of(&tx.signed_encoding(&r, &s, y)),
            f["signed_rlp"].as_str().unwrap(),
            "{name}: signed RLP differs from viem"
        );
    }
}

#[test]
fn the_fixture_set_covers_the_rlp_edge_cases() {
    // A guard against someone trimming the fixtures to a single happy path.
    let doc: serde_json::Value = serde_json::from_str(FIXTURES).unwrap();
    let names: Vec<&str> = doc["fixtures"]
        .as_array()
        .unwrap()
        .iter()
        .map(|f| f["name"].as_str().unwrap())
        .collect();
    for required in [
        "zero_priority_fee",
        "large_values_long_payload",
        "single_byte_boundary",
    ] {
        assert!(names.contains(&required), "fixture {required} is missing");
    }
}

// ---------------------------------------------------------------- RLP rules

#[test]
fn zero_encodes_as_the_empty_string_not_a_zero_byte() {
    // The classic RLP mistake. 0x00 would be a different, invalid encoding.
    assert_eq!(to_be_minimal(0), Vec::<u8>::new());
    assert_eq!(rlp_uint(0), vec![0x80]);
}

#[test]
fn small_integers_encode_as_themselves() {
    assert_eq!(rlp_uint(1), vec![0x01]);
    assert_eq!(rlp_uint(0x7f), vec![0x7f]);
    // 0x80 is above the single-byte range and needs a length prefix.
    assert_eq!(rlp_uint(0x80), vec![0x81, 0x80]);
}

#[test]
fn integers_are_minimal_big_endian() {
    assert_eq!(to_be_minimal(0x0102), vec![0x01, 0x02]);
    assert_eq!(to_be_minimal(u128::from(u64::MAX)), vec![0xff; 8]);
    assert_eq!(to_be_minimal(u128::MAX), vec![0xff; 16]);
}

// ----------------------------------------------------------- address parsing

#[test]
fn addresses_parse_to_exactly_twenty_bytes() {
    let a = address_bytes("0x1111111111111111111111111111111111111111").unwrap();
    assert_eq!(a, [0x11u8; 20]);
    assert_eq!(address_bytes(DEST_A).unwrap().len(), 20);
}

#[test]
fn malformed_addresses_cannot_reach_transaction_construction() {
    assert!(address_bytes("0x111").is_none(), "too short");
    assert!(
        address_bytes("1111111111111111111111111111111111111111").is_none(),
        "no prefix"
    );
    assert!(
        address_bytes("0x111111111111111111111111111111111111111g").is_none(),
        "non-hex digit"
    );
    assert!(address_bytes("").is_none());
}

// --------------------------------------------------------- parameter rules

fn params(gas: u64, max_fee: u128, tip: u128) -> EvmParams {
    EvmParams {
        nonce: U64(0),
        gas_limit: U64(gas),
        max_fee_per_gas: U128(max_fee),
        max_priority_fee_per_gas: U128(tip),
    }
}

#[test]
fn the_fee_is_gas_limit_times_max_fee_per_gas() {
    // This is the number policy checks. It must be the transaction's real
    // ceiling, not something the caller asserts separately (invariant 9).
    let p = params(21_000, 1_000_000_000, 1_000_000);
    assert_eq!(p.max_fee_wei().unwrap(), 21_000u128 * 1_000_000_000u128);
}

#[test]
fn gas_limit_boundaries_are_enforced() {
    assert!(params(MIN_TRANSFER_GAS, 1, 0).validate().is_ok());
    assert_eq!(
        params(MIN_TRANSFER_GAS - 1, 1, 0).validate(),
        Err(EvmParamsError::GasLimitTooLow),
        "below intrinsic gas the transfer cannot succeed"
    );
    assert!(params(MAX_TRANSFER_GAS, 1, 0).validate().is_ok());
    assert_eq!(
        params(MAX_TRANSFER_GAS + 1, 1, 0).validate(),
        Err(EvmParamsError::GasLimitTooHigh),
        "an absurd gas limit only raises the fee ceiling"
    );
}

#[test]
fn a_tip_above_the_fee_cap_is_rejected_as_viem_rejects_it() {
    assert!(
        params(21_000, 100, 100).validate().is_ok(),
        "tip may equal the cap"
    );
    assert_eq!(
        params(21_000, 100, 101).validate(),
        Err(EvmParamsError::PriorityFeeAboveMaxFee)
    );
}

#[test]
fn a_zero_fee_cap_is_rejected() {
    assert_eq!(
        params(21_000, 0, 0).validate(),
        Err(EvmParamsError::ZeroMaxFee)
    );
}

#[test]
fn a_fee_that_would_overflow_is_rejected_rather_than_wrapping() {
    // Wrapping here would compute a tiny fee for an enormous transaction.
    assert_eq!(
        params(MAX_TRANSFER_GAS, u128::MAX, 0).validate(),
        Err(EvmParamsError::FeeOverflow)
    );
}

// ------------------------------------------- what ends up in the signed bytes

#[test]
fn the_signed_transaction_carries_the_approved_recipient_and_value() {
    vm();
    let to = address_bytes(DEST_A).unwrap();
    let tx = Eip1559Transfer {
        chain_id: BASE_SEPOLIA_CHAIN_ID,
        nonce: 3,
        max_priority_fee_per_gas: 1_000_000,
        max_fee_per_gas: 1_000_000_000,
        gas_limit: 21_000,
        to,
        value: 777_000_000_000_000,
    };
    let encoded = tx.unsigned_encoding();

    // The recipient appears verbatim, and exactly once.
    let occurrences = encoded.windows(20).filter(|w| *w == to).count();
    assert_eq!(occurrences, 1, "exactly one recipient may appear");

    // The value appears as a minimal big-endian integer.
    let value_bytes = to_be_minimal(777_000_000_000_000);
    assert!(
        encoded
            .windows(value_bytes.len())
            .any(|w| w == value_bytes.as_slice()),
        "the approved value must be present in the signed bytes"
    );

    // Type byte and chain id.
    assert_eq!(encoded[0], 0x02, "must be a typed EIP-1559 transaction");
    let chain_bytes = to_be_minimal(u128::from(BASE_SEPOLIA_CHAIN_ID));
    assert!(encoded
        .windows(chain_bytes.len())
        .any(|w| w == chain_bytes.as_slice()));
}

#[test]
fn changing_any_approved_field_changes_the_signing_hash() {
    vm();
    let base = Eip1559Transfer {
        chain_id: BASE_SEPOLIA_CHAIN_ID,
        nonce: 1,
        max_priority_fee_per_gas: 1,
        max_fee_per_gas: 100,
        gas_limit: 21_000,
        to: address_bytes(DEST_A).unwrap(),
        value: 1_000,
    };
    let h = base.signing_hash();

    let mut other_to = base.clone();
    other_to.to = address_bytes(DEST_B).unwrap();
    assert_ne!(
        h,
        other_to.signing_hash(),
        "recipient must bind the signature"
    );

    let mut other_value = base.clone();
    other_value.value = 1_001;
    assert_ne!(
        h,
        other_value.signing_hash(),
        "value must bind the signature"
    );

    let mut other_chain = base.clone();
    other_chain.chain_id = 1;
    assert_ne!(
        h,
        other_chain.signing_hash(),
        "chain id must bind the signature"
    );

    let mut other_nonce = base.clone();
    other_nonce.nonce = 2;
    assert_ne!(
        h,
        other_nonce.signing_hash(),
        "nonce must bind the signature"
    );
}

#[test]
fn the_transaction_has_no_calldata_and_no_access_list() {
    vm();
    let tx = Eip1559Transfer {
        chain_id: BASE_SEPOLIA_CHAIN_ID,
        nonce: 0,
        max_priority_fee_per_gas: 0,
        max_fee_per_gas: 1,
        gas_limit: 21_000,
        to: address_bytes(DEST_A).unwrap(),
        value: 1,
    };
    let encoded = tx.unsigned_encoding();
    // A plain transfer ends with empty data (0x80) and an empty access list
    // (0xc0). There is no struct field that could carry calldata, so this is a
    // regression guard on that property rather than on a runtime check.
    assert_eq!(
        &encoded[encoded.len() - 2..],
        &[0x80, 0xc0],
        "data and access_list must both be empty"
    );
}
